    FOOT_BY_html: 'Parallax Launcher — created by Arda Yalın Özkan.<br> Free software under the <a href="https://github.com/ArdaYalinOzkan/parallax-launcher/blob/main/LICENSE">GNU GPL v3</a>.',
    FOOT_GUIDES: 'All guides',
